import sys

def max_path_length(v1, v2, t, d):
    if v1 == v2:
        return v1 * t

    if v1 < v2:
        max_speed = v1 + d
        min_speed = max(v2 - d, v1)
    else:
        max_speed = min(v1 - d, v2)
        min_speed = v2 + d

    if max_speed < min_speed:
        return (v1 + v2) * t // 2

    max_length = 0
    current_speed = v1

    for _ in range(t):
        max_length += current_speed
        if current_speed < v2:
            current_speed = min(current_speed + d, v2)
        elif current_speed > v2:
            current_speed = max(current_speed - d, v2)

    return max_length

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    v1 = int(data[0])
    v2 = int(data[1])
    t = int(data[2])
    d = int(data[3])

    result = max_path_length(v1, v2, t, d)
    print(result)

if __name__ == "__main__":
    main()
